import { test, expect } from '@playwright/test';

test.describe('Order Summary Before Payment Confirmation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/cart');
  });

  test('should display order summary before payment confirmation', async ({ page }) => {
    // Verify cart page loads
    await expect(page.getByRole('heading', { name: /cart/i })).toBeVisible();

    // Add item to cart
    const addButton = page.getByRole('button', { name: /add to cart/i });
    await addButton.click();

    // Verify item is in cart
    const itemRow = page.getByText('Product Name');
    await expect(itemRow).toBeVisible();

    // Verify subtotal is displayed
    const subtotal = page.getByText(/\$\d+\.\d{2}/);
    await expect(subtotal).toBeVisible();

    // Verify total is displayed
    const total = page.getByText(/\$\d+\.\d{2}/);
    await expect(total).toBeVisible();

    // Click checkout button
    const checkoutButton = page.getByRole('button', { name: /checkout/i });
    await checkoutButton.click();

    // Verify order summary page loads
    await expect(page.getByRole('heading', { name: /order summary/i })).toBeVisible();

    // Verify order details are visible
    const orderDetails = page.getByRole('region', { name: /order details/i });
    await expect(orderDetails).toBeVisible();

    // Verify total amount is displayed in summary
    const summaryTotal = page.getByText(/\$\d+\.\d{2}/);
    await expect(summaryTotal).toBeVisible();

    // Verify payment options are available
    const paymentOptions = page.getByRole('group', { name: /payment options/i });
    await expect(paymentOptions).toBeVisible();

    // Click confirm payment button
    const confirmButton = page.getByRole('button', { name: /confirm payment/i });
    await confirmButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/payment successful/i);
    await expect(successMessage).toBeVisible();
  });

  test('should handle empty cart and prevent checkout', async ({ page }) => {
    // Verify cart page loads
    await expect(page.getByRole('heading', { name: /cart/i })).toBeVisible();

    // Verify empty cart message is displayed
    const emptyCartMessage = page.getByText(/your cart is empty/i);
    await expect(emptyCartMessage).toBeVisible();

    // Verify checkout button is disabled or not present
    const checkoutButton = page.getByRole('button', { name: /checkout/i });
    await expect(checkoutButton).not.toBeVisible();

    // Attempt to navigate to checkout directly
    await page.goto('/checkout');

    // Verify empty cart message persists on checkout page
    const checkoutEmptyMessage = page.getByText(/your cart is empty/i);
    await expect(checkoutEmptyMessage).toBeVisible();

    // Verify order summary section is not displayed
    const orderSummary = page.getByRole('region', { name: /order summary/i });
    await expect(orderSummary).not.toBeVisible();

    // Verify user is prompted to add items
    const promptMessage = page.getByText(/please add items to your cart/i);
    await expect(promptMessage).toBeVisible();
  });
});
